SELECT COUNT(*)
FROM (
SELECT DISTINCT cust_id
FROM topp_order
WHERE order_type = #{orderType}
AND create_time >= '2024-01-01 00:00:00'
AND create_time <= #{endTime}
) a

SELECT COUNT(1)
FROM topp_order to2
WHERE order_type = #{orderType}
  AND create_time >= '2024-01-01 00:00:00'
  AND create_time <= #{date}

SELECT COUNT(1)
FROM topp_order to2
WHERE order_type = #{orderType}
  AND create_time >= '2024-01-01 00:00:00'
  AND create_time <= #{date}
  AND status_ = 'end'
